const chats=[
 {name:'Lena Park',initial:'L',style:'amber',online:true,preview:'That sounds perfect, thank you!',time:'10:42',messages:[['them','Hey! Do you have a minute to review the launch notes?','10:31'],['me','Absolutely. I just finished a first pass through the product flow.','10:34'],['them','Amazing. I love how calm and focused it feels.','10:38'],['them','That sounds perfect, thank you!','10:42']]},
 {name:'Design Studio',initial:'D',style:'violet',online:false,preview:'Maya shared a new board',time:'09:18',messages:[['them','Maya shared a new inspiration board.','09:18'],['me','I will take a look after lunch.','09:22']]},
 {name:'Arjun Mehta',initial:'A',style:'sky',online:true,preview:'Let’s catch up tomorrow.',time:'Yesterday',messages:[['them','Let’s catch up tomorrow.','Yesterday']]},
 {name:'Weekend plans',initial:'W',style:'rose',online:false,preview:'3 new messages',time:'Mon',messages:[['them','Coffee this weekend?','Mon'],['me','Yes, please!','Mon']]}
];let active=0;const list=document.querySelector('#conversationList'),area=document.querySelector('#messageArea'),input=document.querySelector('#messageInput'),toast=document.querySelector('#toast');
function avatar(chat){return `<div class="avatar avatar-${chat.style}">${chat.initial}</div>`}function renderList(){let filter=document.querySelector('#search').value.toLowerCase();list.innerHTML=chats.map((c,i)=>!c.name.toLowerCase().includes(filter)?'':`<button class="conversation ${i===active?'active':''}" data-id="${i}">${avatar(c)}<span><strong>${c.name}</strong><p>${c.preview}</p></span><time>${c.time}</time></button>`).join('');list.querySelectorAll('.conversation').forEach(el=>el.onclick=()=>{active=+el.dataset.id;render();document.querySelector('#sidebar').classList.remove('open')})}function render(){let chat=chats[active];document.querySelector('#chatTitle').textContent=chat.name;document.querySelector('#headerAvatar').textContent=chat.initial;document.querySelector('#headerAvatar').className=`avatar avatar-${chat.style}`;document.querySelector('#chatPresence').innerHTML=chat.online?'<i></i> Online now':'Last seen recently';area.innerHTML='<p class="day-marker">TODAY</p>'+chat.messages.map(([who,text,time])=>`<article class="message ${who}">${who==='them'?avatar(chat):'<div class="avatar avatar-sky">M</div>'}<div class="bubble">${text}<time class="time">${time}${who==='me'?' · ✓✓':''}</time></div></article>`).join('');renderList();area.scrollTop=area.scrollHeight}function clock(){return new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}function send(){let text=input.value.trim();if(!text)return;let chat=chats[active];chat.messages.push(['me',text,clock()]);chat.preview=text;chat.time='now';input.value='';render();if(chat.online){let typing=document.querySelector('#typing');typing.textContent=`${chat.name.split(' ')[0]} is typing`;typing.classList.add('show');setTimeout(()=>{typing.classList.remove('show');chat.messages.push(['them','Got it — I’ll get back to you shortly.','now']);chat.preview='Got it — I’ll get back to you shortly.';render()},1300)}}function notify(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)}document.querySelector('#composer').onsubmit=e=>{e.preventDefault();send()};document.querySelector('#search').oninput=renderList;document.querySelector('#mobileMenu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#newChat').onclick=()=>notify('New conversation is ready to start.');document.querySelector('.emoji').onclick=()=>{input.value+=' 😊';input.focus()};document.querySelector('.attach').onclick=()=>notify('File attachments are ready for your next update.');render();
